import{_ as s,C as e,o as i,c as d,j as o,a as p,G as a,a3 as g}from"./chunks/framework.Bvm_liKL.js";const C=JSON.parse('{"title":"常见问题","description":"ICC-CE 使用过程中最常遇到的问题与解决办法","frontmatter":{"title":"常见问题","description":"ICC-CE 使用过程中最常遇到的问题与解决办法"},"headers":[],"relativePath":"cn/guide/faq.md","filePath":"cn/guide/faq.md"}'),c={name:"cn/guide/faq.md"};function l(h,t,u,f,P,_){const r=e("ArticleMetadata"),n=e("UnderConstruction");return i(),d("div",null,[t[0]||(t[0]=o("h1",{id:"常见问题",tabindex:"-1"},[p("常见问题 "),o("a",{class:"header-anchor",href:"#常见问题","aria-label":'Permalink to "常见问题"'},"​")],-1)),a(r),a(n),t[1]||(t[1]=g('<h2 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h2><p><strong>双击没反应 / 一闪而过</strong> 最常见的原因是缺少 <strong>.NET 6 桌面运行时</strong>。请到微软官网下载 “.NET Desktop Runtime 6.x” 并按系统位数安装。 若仍然无法启动，查看 <code>CrashLogs</code> 目录中的报告。</p><p><strong>杀毒软件报毒</strong> ICC-CE 需要创建透明置顶窗口并读取触控输入，部分安全软件会误报。请从官方发布页下载并添加信任。 若不放心，可对照发布页的文件校验信息核验。</p><p><strong>32 位还是 64 位</strong> 现代设备一律用 64 位。只有系统本身是 32 位时才选 32 位版本。</p><h2 id="书写与显示" tabindex="-1">书写与显示 <a class="header-anchor" href="#书写与显示" aria-label="Permalink to &quot;书写与显示&quot;">​</a></h2><p><strong>写字有明显延迟</strong> 依次尝试：确认设备驱动为厂商官方驱动、在设置中开启硬件加速墨迹渲染、关闭其他占用 GPU 的程序。 老旧设备可适当降低墨迹平滑强度。</p><p><strong>笔迹粗细不均匀</strong> 这是压感生效的表现。不需要压感时可在设置中关闭压感响应，笔迹会变成均匀粗细。</p><p><strong>画完的形状自动变成了规整图形</strong> 形状识别被触发了。不需要时可在设置中关闭形状识别，或改为需要长按才触发。</p><p><strong>多点触控失灵</strong> 先确认设备支持多点触控（设备管理器中能看到 HID 兼容触摸屏），再检查设置中的手势开关是否被关闭。</p><h2 id="手势与操作" tabindex="-1">手势与操作 <a class="header-anchor" href="#手势与操作" aria-label="Permalink to &quot;手势与操作&quot;">​</a></h2><p><strong>双指缩放不起作用</strong> 检查设置中的手势总开关与缩放手势开关。部分老旧一体机的触摸驱动会把双指手势直接吞掉， 这种情况下需要更新触摸驱动。</p><p><strong>误触频繁</strong> 开启掌压屏蔽（防误触）相关选项，并适当增大触摸判定阈值。</p><h2 id="powerpoint-联动" tabindex="-1">PowerPoint 联动 <a class="header-anchor" href="#powerpoint-联动" aria-label="Permalink to &quot;PowerPoint 联动&quot;">​</a></h2><p><strong>放映时没有出现 PPT 按钮</strong> 确认使用的是桌面版 PowerPoint，且未被安全策略拦截 COM 调用。详见<a href="/website/cn/guide/ppt-guide">PPT 联动指南</a>。</p><p><strong>墨迹没有被保存</strong> 检查自动保存开关与目标目录的写入权限。</p><p><strong>加载项装了但没生效</strong> Office 可能因启动缓慢自动禁用了它，到「文件 → 选项 → 加载项 → 管理：禁用项目」中重新启用。</p><h2 id="设置与数据" tabindex="-1">设置与数据 <a class="header-anchor" href="#设置与数据" aria-label="Permalink to &quot;设置与数据&quot;">​</a></h2><p><strong>设置改了但重启后失效</strong> 多半是程序没有正常退出（被强制结束进程），配置来不及写盘。请用正常方式退出。 若目录只读（机房还原环境），需要把数据目录换到可写分区。</p><p><strong>想把设置同步到其他机器</strong> 复制 <code>Settings.json</code> 到目标机器的相同位置即可，详见<a href="/website/cn/guide/files-and-data">配置文件与数据目录</a>。</p><p><strong>改坏了配置怎么恢复</strong> 直接删除 <code>Settings.json</code>，程序下次启动会重新生成默认配置。</p><h2 id="版本与更新" tabindex="-1">版本与更新 <a class="header-anchor" href="#版本与更新" aria-label="Permalink to &quot;版本与更新&quot;">​</a></h2><p><strong>该用哪个通道</strong> 日常使用选 <strong>Beta</strong>，追求稳定选 <strong>正式版</strong>，<strong>Nightly 不要用于正式课堂</strong>。 详见<a href="/website/cn/guide/installation">安装与更新通道</a>。</p><p><strong>下载很慢或下载失败</strong> 下载页会自动选择最快线路。若仍然失败，可换一个通道试试，或直接到 GitHub 发布页手动下载。</p><p><strong>能不能退回旧版本</strong> 可以。在下载页用「上一版 / 下一版」翻到目标版本下载即可。跨版本回退时如遇异常， 备份后删除配置文件重新生成。</p><h2 id="反馈问题" tabindex="-1">反馈问题 <a class="header-anchor" href="#反馈问题" aria-label="Permalink to &quot;反馈问题&quot;">​</a></h2><p>提交 Issue 时请附上：ICC-CE 版本号、系统版本、复现步骤、以及 <code>Logs</code> 与 <code>CrashLogs</code> 中对应时间的文件。 信息越完整定位越快。</p>',26))])}const b=s(c,[["render",l]]);export{C as __pageData,b as default};
